using System;

public class ErrorBudgetCalculator
{
    public static (double allowedDowntimeMinutes, double budgetBurnPercentage) CalculateBudget(
        double targetSloPercentage, 
        double totalPeriodMinutes, 
        double actualDowntimeMinutes)
    {
        double allowed = totalPeriodMinutes * ((100.0 - targetSloPercentage) / 100.0);
        double burn = (actualDowntimeMinutes / allowed) * 100.0;
        return (allowed, burn);
    }
}

public class Program
{
    public static void Main()
    {
        double slo = 99.9;
        double periodMinutes = 30 * 24 * 60; // 43.200 menit
        double actualDowntime = 21.6;

        var (allowed, burn) = ErrorBudgetCalculator.CalculateBudget(slo, periodMinutes, actualDowntime);

        Console.WriteLine($"Target SLO            : {slo}%");
        Console.WriteLine($"Batas Downtime Bulanan: {allowed:F1} menit");
        Console.WriteLine($"Downtime Aktual       : {actualDowntime:F1} menit");
        Console.WriteLine($"Error Budget Terbakar : {burn:F1}%");

        if (burn > 100.0)
        {
            Console.WriteLine("[KEBIJAKAN SRE] Error Budget HABIS! Rilis fitur baru DIBEKUKAN (Feature Freeze).");
        }
        else
        {
            Console.WriteLine("[KEBIJAKAN SRE] Error Budget masih aman. Rilis fitur diizinkan.");
        }
    }
}
